// Schema Check + Defaults (SAFE) — SW3 Upload
// JSON-only flags (no $env/process), preserve wiring, add top-level mirrors.

const jIn = $json || {};
const b   = $binary || {};

/* helpers */
const num   = (v,d)=>Number.isFinite(+v)?+v:d;
const pick  = (...v)=>v.find(x=>x!==undefined&&x!==null&&x!=='');
const asInt = (v)=>{ const n = Number(v); return Number.isFinite(n) ? Math.floor(n) : null; };

/* flags & defaults */
const isTest = !!(jIn.__testMode || jIn.testMode || jIn.__meta?.__testMode || jIn.ctx?.__testMode || jIn.ctx?.testMode);
const route  = jIn.__route || (isTest ? 'TEST' : 'REAL');

const assetsRoot   = jIn.assetsRoot   || 'book-mvp-simple-adventure/order-generated-assets';
// UPDATE: Removed hardcoded publicR2Url fallback - use backend proxy or signed URLs for external access
const publicR2Url  = jIn.publicR2Url  || null;
const templatePath = jIn.templatePath || 'templates';
const ctx = jIn.ctx || {};

/* identity */
const characterHash = pick(jIn.characterHash, ctx.characterHash, jIn.__meta?.characterHash, null);
const poseNum = num(pick(jIn.pose?.poseNumber, jIn.poseNumber, jIn.currentPoseNumber), null);

/* required checks */
function req(ok, msg){ if(!ok) throw new Error(msg); }
req(!!characterHash, 'SW3 Schema: characterHash is required');
req(Number.isFinite(poseNum), 'SW3 Schema: poseNumber is required');

/* retry (robust, default 0) */
const retryAttempt = asInt(pick(jIn.retryAttempt, jIn.retry?.attempt, jIn.qaRetry)) ?? 0;
const retryTag     = pick(jIn.retryTag, jIn.retry?.tag, (retryAttempt > 0 ? `retry${retryAttempt}` : '')) || '';

/* pass flags (mirror for Prepare Upload) */
const qaCombinedPass = !!(jIn.qaCombinedPass === true || jIn.combinedQaPass === true || jIn.qa?.combined?.pass === true);
const qaPassTop      = !!(jIn.qaPass === true || qaCombinedPass);

/* carry IDs that Prepare Upload uses for key building */
const correlationId = pick(jIn.correlationId, jIn.__meta?.correlationId, null);
const amazonOrderId = pick(
  jIn.amazonOrderId,
  jIn.orderId,
  jIn.orderContext?.amazonOrderId,
  jIn.orderContext?.orderId,
  jIn.orderData?.amazonOrderId,
  jIn.orderData?.orderId,
  jIn.__meta?.amazonOrderId,
  jIn.__meta?.orderId,
  jIn.__meta?.deriveQaPass?.snapshot?.amazonOrderId,
  jIn.__meta?.deriveQaPass?.snapshot?.orderId,
  jIn.__meta?.deriveQaPass?.snapshot?.rootOrderId,
  jIn.__meta?.deriveQaPass?.snapshot?.orderContext?.amazonOrderId,
  jIn.__meta?.deriveQaPass?.snapshot?.orderContext?.orderId,
  null
);
const generatedFileName = pick(jIn.generatedFileName, null);

/* build lean envelope (keep nested shapes + add top-level mirrors) */
const out = {
  // ---- top-level mirrors (NEW) ----
  characterHash,
  poseNumber: Number(poseNum),
  retryAttempt,
  retryTag,
  qaPass: qaPassTop,
  qaCombinedPass,

  correlationId,
  amazonOrderId,
  orderId: amazonOrderId,
  generatedFileName,

  // ---- existing nested shapes (kept for compatibility) ----
  ctx: { ...ctx, characterHash },
  pose: { poseNumber: Number(poseNum) },
  retry: { attempt: retryAttempt, tag: retryTag },

  // QA block passthrough
  qa: jIn.qa || {},
  orderContext: jIn.orderContext || jIn.__meta?.deriveQaPass?.snapshot?.orderContext || null,
  orderData: {
    ...(jIn.orderData || {}),
    amazonOrderId: pick(jIn.orderData?.amazonOrderId, amazonOrderId, null),
    orderId: pick(jIn.orderData?.orderId, amazonOrderId, null)
  },

  // normalized defaults
  assetsRoot, publicR2Url, templatePath,

  // route/test flags
  __route: route,
  __testMode: isTest,
  testMode: isTest,

  // preserve meta + size budget
  __meta: { ...(jIn.__meta || {}), __testMode: isTest, sizeBudget: jIn.__meta?.sizeBudget ?? 120000, amazonOrderId: pick(jIn.__meta?.amazonOrderId, amazonOrderId, null), orderId: pick(jIn.__meta?.orderId, amazonOrderId, null) }
};

/* binaries expected by Prepare Upload (rehydrates if needed) */
const bin = {
  character: b.character || null,
  pose: b.pose || null,
  generated: b.generated || b.generated_inline || null,
};

return { json: out, binary: bin };

// Capture Lean Meta — SW3 v3.2 (ZERO-SAFE + pose00 inference)
// - Preserves poseNumber: 0 even if allowZeroPose flag is missing
// - Infers zero-mode from filenames/keys/QA snapshots (pose00 hints)
// - Reads storageKey/uploadedFilename from SW1's __meta if present
// - Falls back to computing paths that match your live structure
// - Uses poseNN.png (no dash): pose00.png, pose03_r1.png
// - Uses /poses/ subfolder
// - Uses _r1, _r2 retry format (NOT _try01)

const j  = $json   || {};
const b  = $binary || {};
const ix = (typeof $itemIndex === 'number') ? $itemIndex : 0;

/* helpers */
function firstDefined(...vals){ for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; } }
function asInt(v){ const n = Number(v); return Number.isFinite(n) ? Math.floor(n) : null; }
function pad2(n){ return String(n).padStart(2,'0'); }
function hasPose00Str(s){ return typeof s === 'string' && /(?:^|\/|_)(pose[-_]?0{2})(?:\.|_|\/|$)/i.test(s); }

/* 0) zero policy from upstream + inference */
const upstreamZero =
  j.__meta?.allowZeroPose === true ||
  j.allowZeroPose === true ||
  j.orderContext?.allowZeroPose === true ||
  false;

// Infer zero-based mode if we detect pose00 in any credible field
const zeroHint =
  hasPose00Str(j.generatedFileName) ||
  hasPose00Str(j.storageKey)        ||
  hasPose00Str(j.uploadKey)         ||
  hasPose00Str(j.__meta?.storageKey)||
  hasPose00Str(j.__meta?.uploadedFilename) ||
  j.pose?.poseNumber === 0 ||
  j.poseNumber === 0 ||
  j.currentPoseNumber === 0 ||
  j.index === 0 ||
  // QA breadcrumbs
  (j.__meta?.deriveQaPass?.snapshot?.expectedPoseNumber === 0) ||
  (j.__meta?.styleQaBuildRequest?.partsSummary?.poseNN_plain === 'pose00') ||
  (j.__meta?.styleQaBuildRequest?.partsSummary?.poseNN_hyphen === 'pose-00');

const allowZero = upstreamZero || zeroHint;

/* 1) resolve identity */
const characterHash = firstDefined(j.characterHash, j.ctx?.characterHash, j.orderData?.characterHash);
if (!characterHash || String(characterHash).trim().length < 4) {
  throw new Error('Capture Lean Meta (SW3): characterHash is missing.');
}

/* 2) resolve pose number (ZERO-SAFE) */
let poseRaw = firstDefined(
  j.poseNumber,
  j.currentPoseNumber,
  j.pose?.poseNumber,
  j.__meta?.poseNumber,
  // LAST resort: derive from item index; respect zero policy
  allowZero ? ix : (ix + 1)
);
let poseNumber = asInt(poseRaw);
if (poseNumber === null) poseNumber = allowZero ? 0 : 1;

// Respect zero if any hints say this is pose00
if (zeroHint && poseNumber === 1) poseNumber = 0;

// Guardrails (upper only)
const maxPose = 99;
if (poseNumber > maxPose) poseNumber = maxPose;

const NN = pad2(poseNumber);

/* 3) retry info (match SW1 format: _r1, _r2, NOT _try01) */
const retryAttempt = asInt(firstDefined(j.retryAttempt, j.retry?.attempt, j.qaRetry)) || 0;
const retryTag = firstDefined(j.retryTag, j.retry?.tag, retryAttempt ? `r${retryAttempt}` : '') || '';
const retrySuffix = retryAttempt > 0 ? `_r${retryAttempt}` : '';

/* 4) SW1-provided keys (single source of truth if present) */
const sw1StorageKey = j.__meta?.storageKey || j.uploadKey;
const sw1Filename   = j.__meta?.uploadedFilename || j.generatedFileName;

/* 5) Choose keys */
let storageKey, filename;
if (sw1StorageKey) {
  storageKey = sw1StorageKey;
  // Prefer SW1 filename if present, otherwise synthesize poseNN form
  filename = sw1Filename || `pose${NN}${retrySuffix}.png`;
  console.log('✓ Using SW1-provided storageKey:', storageKey);
} else {
  const ASSETS_ROOT_FALLBACK = firstDefined(j.assetsRoot, 'book-mvp-simple-adventure/order-generated-assets');
  filename  = `pose${NN}${retrySuffix}.png`;
  storageKey = `${ASSETS_ROOT_FALLBACK}/characters/${characterHash}/poses/${filename}`;
  console.log('⚠ Computing storageKey (SW1 did not provide):', storageKey);
}

/* 6) Sanitize */
storageKey = storageKey.replace(/\/{2,}/g, '/');

/* 7) paths & URLs */
const ASSETS_ROOT = firstDefined(j.assetsRoot, 'book-mvp-simple-adventure/order-generated-assets');
const PUBLIC_R2   = firstDefined(j.publicR2Url, 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev');
const characterPath = `${ASSETS_ROOT}/characters/${characterHash}`;

/* 8) order ID */
const amazonOrderId = firstDefined(
  j.amazonOrderId,
  j.orderId,
  j.orderContext?.amazonOrderId,
  j.orderContext?.orderId,
  j.orderData?.amazonOrderId,
  j.orderData?.orderId,
  j.__meta?.amazonOrderId,
  j.__meta?.orderId,
  j.__meta?.deriveQaPass?.snapshot?.amazonOrderId,
  j.__meta?.deriveQaPass?.snapshot?.orderId,
  j.__meta?.deriveQaPass?.snapshot?.rootOrderId,
  j.__meta?.deriveQaPass?.snapshot?.orderContext?.amazonOrderId,
  j.__meta?.deriveQaPass?.snapshot?.orderContext?.orderId,
  'unknown-order'
);

/* 9) bytes if available */
const approxBytes =
  asInt(b?.generated?.fileSize)        ??
  asInt(b?.generated_inline?.fileSize) ??
  asInt(j.generatedImage?.size)        ??
  j.__meta?.bytes                      ??
  j.fileSize                           ??
  null;

/* 10) build output */
const out = {
  ...j,

  // normalized mirrors
  characterHash,
  poseNumber,
  currentPoseNumber: poseNumber,
  index: allowZero ? poseNumber : (poseNumber - 1),
  amazonOrderId,
  orderId: firstDefined(j.orderId, amazonOrderId),

  // retry mirrors
  retryAttempt: firstDefined(j.retryAttempt, retryAttempt),
  retryTag: firstDefined(j.retryTag, retryTag),

  // asset roots / urls
  assetsRoot: ASSETS_ROOT,
  publicR2Url: PUBLIC_R2,

  // key/filename
  characterPath,
  storageKey,
  uploadKey: storageKey,
  generatedFileName: filename,

  // orderData coherence
  orderContext: j.orderContext || j.__meta?.deriveQaPass?.snapshot?.orderContext || null,
  orderData: {
    ...(j.orderData || {}),
    amazonOrderId,
    orderId: firstDefined(j.orderData?.orderId, amazonOrderId),
    characterHash,
    characterPath,
    r2BucketName: firstDefined(j.orderData?.r2BucketName, 'little-hero-assets'),
  },

  __meta: {
    ...(j.__meta || {}),
    amazonOrderId: firstDefined(j.__meta?.amazonOrderId, amazonOrderId),
    orderId: firstDefined(j.__meta?.orderId, amazonOrderId),
    allowZeroPose: allowZero,
    poseNumber,
    characterHash,
    characterPath,
    storageKey,
    uploadedFilename: filename,
    bytes: approxBytes ?? undefined,
    sw1Compatible: true,
    captureLeanMeta: {
      version: '3.2',
      source: sw1StorageKey ? 'sw1_provided' : 'computed_fallback',
      filename,
      retryAttempt,
      retrySuffix,
      amazonOrderId,
      allowZeroPose: allowZero,
      zeroInference: {
        upstreamZero,
        zeroHint,
        hints: {
          generatedFileName: hasPose00Str(j.generatedFileName) || undefined,
          storageKey:        hasPose00Str(j.storageKey)        || undefined,
          uploadKey:         hasPose00Str(j.uploadKey)         || undefined,
          metaStorageKey:    hasPose00Str(j.__meta?.storageKey)|| undefined,
          metaUploaded:      hasPose00Str(j.__meta?.uploadedFilename) || undefined,
          poseFieldZero:     (j.pose?.poseNumber === 0) || undefined,
          directZero:        (j.poseNumber === 0 || j.currentPoseNumber === 0) || undefined,
          indexZero:         (j.index === 0) || undefined,
          qaExpectedZero:    (j.__meta?.deriveQaPass?.snapshot?.expectedPoseNumber === 0) || undefined,
          qaPlainZero:       (j.__meta?.styleQaBuildRequest?.partsSummary?.poseNN_plain === 'pose00') || undefined,
          qaHyphenZero:      (j.__meta?.styleQaBuildRequest?.partsSummary?.poseNN_hyphen === 'pose-00') || undefined
        }
      }
    }
  }
};

console.log('✅ Capture Lean Meta v3.2', {
  item: ix,
  allowZeroPose: allowZero,
  zeroHint,
  poseNumber,
  index: out.index,
  amazonOrderId,
  filename,
  storageKey,
  retryAttempt,
  source: sw1StorageKey ? 'SW1' : 'fallback',
  bytes: approxBytes ?? 'n/a'
});

return {
  json: out,
  binary: b,
  pairedItem: ($input?.item?.pairedItem) ? $input.item.pairedItem : { item: ix }
};

// Prepare Upload (per-item, PASS branch only) — v2.3 (direct canonical finalize)
// - Preserves poseNumber: 0 when explicitly provided
// - Refuses to invent amazonOrderId / poseNumber fallback values
// - Prefers SW1-provided __meta.storageKey/uploadedFilename (single source of truth)
// - Fallback filename format matches live structure: poseNN[_rM].png (NO dash), /poses/ subfolder
// - Uses retry suffix _r1, _r2
// - Removes legacy temporaryR2Key staging state from the active path

const j0 = $json   || {};
const b0 = $binary || {};
const out = { json: { ...j0 }, binary: { ...b0 } };

/* helpers */
function firstDefined(...vals){ for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; } }
function asInt(v){ const n = Number(v); return Number.isFinite(n) ? Math.floor(n) : null; }
function pad2(n){ return String(n).padStart(2,'0'); }
function isNonEmptyStr(x){ return typeof x === 'string' && x.trim().length > 0; }
function hasPose00Str(s){ return typeof s === 'string' && /(?:^|\/|_)(pose[-_]?0{2})(?:\.|_|\/|$)/i.test(s); }

/* 0) strict pass gate */
const passed =
  j0.qaPass === true ||
  j0.qaCombinedPass === true ||
  (j0.qa && j0.qa.combined && j0.qa.combined.pass === true) ||
  j0.qaRetryPass === true;

if (!passed) {
  throw new Error('Prepare Upload: not on QA-pass path (qaPass/qaCombinedPass/qa.combined.pass).');
}

/* 1) choose the passing binary */
let gen = out.binary.generated || out.binary.final_generated || out.binary.generated_inline || null;
let sourceTag =
  (out.binary.generated ? 'generated'
    : out.binary.final_generated ? 'final_generated'
    : out.binary.generated_inline ? 'generated_inline'
    : null);

if (!gen) {
  const keys = Object.keys(out.binary || {});
  throw new Error(`Prepare Upload: missing image binary. Expected "generated". Present keys: [${keys.join(', ')}]`);
}

/* 2) identity */
const hash = firstDefined(
  out.json.characterHash,
  out.json.__meta?.characterHash,
  out.json.ctx?.characterHash
);
if (!isNonEmptyStr(hash) || hash.length < 4) {
  throw new Error('Prepare Upload: characterHash missing/invalid.');
}

/* 3) ZERO-SAFE pose resolution */
const explicitPoseRaw = firstDefined(
  out.json.poseNumber,
  out.json.currentPoseNumber,
  out.json.__meta?.poseNumber,
  out.json.pose?.poseNumber
);
const poseNum = asInt(explicitPoseRaw);
if (poseNum === null || poseNum < 0 || poseNum > 99) {
  throw new Error(`Prepare Upload: valid poseNumber is required before canonical publish. Received: ${String(explicitPoseRaw)}`);
}
const allowZero = poseNum === 0 ||
  out.json.__meta?.allowZeroPose === true ||
  out.json.allowZeroPose === true ||
  out.json.orderContext?.allowZeroPose === true ||
  hasPose00Str(out.json.generatedFileName) ||
  hasPose00Str(out.json.storageKey) ||
  hasPose00Str(out.json.uploadKey) ||
  hasPose00Str(out.json.__meta?.storageKey) ||
  hasPose00Str(out.json.__meta?.uploadedFilename);
const NN = pad2(poseNum);

/* 4) retry info */
const retryAttempt = asInt(firstDefined(
  out.json.retryAttempt,
  out.json.qaRetry,
  out.json.__meta?.qaRetry
)) || 0;
const retrySuffix = retryAttempt > 0 ? `_r${retryAttempt}` : '';

/* 5) Use SW1-provided keys if available (single source of truth) */
let storageKey = out.json.__meta?.storageKey || out.json.uploadKey;
let filename   = out.json.__meta?.uploadedFilename || out.json.generatedFileName;

if (!storageKey || !filename) {
  const ASSETS_ROOT = firstDefined(out.json.assetsRoot, 'book-mvp-simple-adventure/order-generated-assets');
  filename  = `pose${NN}${retrySuffix}.png`;
  storageKey = `${ASSETS_ROOT}/characters/${hash}/poses/${filename}`.replace(/\/{2,}/g, '/');
  console.log('⚠ Computed storageKey (not provided by SW1):', storageKey);
} else {
  console.log('✓ Using SW1-provided storageKey:', storageKey);
}

/* 6) normalize binary */
const normalized = {
  ...gen,
  fileName: filename,
  mimeType: gen.mimeType || 'image/png',
  fileExtension: gen.fileExtension || 'png',
};
out.binary = { generated: normalized };

/* 7) annotate JSON */
const DEFAULT_R2 = 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev';
out.json.publicR2Url = out.json.publicR2Url || DEFAULT_R2;
const amazonOrderId = String(firstDefined(
  out.json.amazonOrderId,
  out.json.orderId,
  out.json.orderContext?.amazonOrderId,
  out.json.orderContext?.orderId,
  out.json.orderData?.amazonOrderId,
  out.json.orderData?.orderId,
  out.json.__meta?.amazonOrderId,
  out.json.__meta?.orderId,
  out.json.__meta?.deriveQaPass?.snapshot?.amazonOrderId,
  out.json.__meta?.deriveQaPass?.snapshot?.orderId,
  out.json.__meta?.deriveQaPass?.snapshot?.rootOrderId,
  out.json.__meta?.deriveQaPass?.snapshot?.orderContext?.amazonOrderId,
  out.json.__meta?.deriveQaPass?.snapshot?.orderContext?.orderId,
  ''
) || '').trim();
if (!amazonOrderId) {
  throw new Error('Prepare Upload: amazonOrderId/orderId is required before canonical publish.');
}

out.json.poseNumber = poseNum;
out.json.currentPoseNumber = poseNum;
out.json.index = allowZero ? poseNum : (poseNum - 1);

const bytes = Number(
  normalized.fileSize ??
  normalized.fileSizeInBytes ??
  normalized.size ??
  j0.generatedImage?.size ??
  j0.__meta?.bytes ??
  NaN
);
const bytesNum = Number.isFinite(bytes) ? bytes : null;

const nextMeta = {
  ...(out.json.__meta || {}),
  allowZeroPose: allowZero,
  storageKey,
  uploadKey: storageKey,
  amazonOrderId,
  orderId: firstDefined(out.json.__meta?.orderId, amazonOrderId),
  uploadedFilename: filename,
  characterHash: hash,
  poseNumber: poseNum,
  bytes: bytesNum,
  sw1Compatible: true,
  prepareUpload: {
    version: '2.3',
    filename,
    source: sourceTag || 'generated',
    usedSW1Keys: !!(out.json.__meta?.storageKey || out.json.uploadKey),
    publishMode: 'direct_file_upload'
  }
};

delete nextMeta.temporaryR2Key;
out.json.__meta = nextMeta;

out.json.characterHash = hash;
out.json.amazonOrderId = amazonOrderId;
out.json.orderId = firstDefined(out.json.orderId, amazonOrderId);
delete out.json.temporaryR2Key;

console.log('✅ Prepare Upload v2.3', {
  itemIndex: $itemIndex,
  poseNum,
  hash: hash.slice(0,8)+'…',
  amazonOrderId,
  filename,
  storageKey,
  bytes: bytesNum,
  source: sourceTag,
  publishMode: 'direct_file_upload'
});

return out;

// Memory Hygiene After Upload (SW3-05) — per-item
const j = $json || {};
const itemIdx = $itemIndex ?? 0;

// clear binaries by returning an empty binary object
const out = {
  json: j,
  binary: {}, // important: single object, not array
  pairedItem: $input?.item?.pairedItem ?? { item: itemIdx },
};

console.log(`🧹 Cleared binaries for ${j.characterHash || 'unknown'} pose ${j.poseNumber ?? j.currentPoseNumber ?? '?'} (item ${itemIdx})`);

if (global && typeof global.gc === 'function') {
  try { global.gc(); } catch {}
}

return out;

// SW3 - Return Upload Results (Complete Data) — v2.2 ZERO-SAFE
// - Preserves pose 0 (no 0→1 coercion)
// - Uses firstDefined() instead of || for numeric pose fields
// - Keeps storageKey/uploadKey symmetry and builds publicUrl safely
// - Does not republish legacy temporaryR2Key staging state

const input = $json || {};

// helpers
function firstDefined(...vals){
  for (const v of vals){
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
}
function joinUrl(base, path){
  if (!base || !path) return undefined;
  return `${String(base).replace(/\/+$/,'')}/${String(path).replace(/^\/+/,'')}`;
}

// zero-safe pose resolution
const poseNumber = firstDefined(
  input.poseNumber,
  input.currentPoseNumber,
  input.__meta?.poseNumber,
  input.pose?.poseNumber,
  input.index
);

// keys/paths
const storageKey = firstDefined(input.storageKey, input.__meta?.storageKey, input.uploadKey, input.r2Key);
const uploadKey  = firstDefined(input.__meta?.uploadKey, input.uploadKey, storageKey, input.r2Key);
const publicUrl  = firstDefined(
  input.publicUrl,
  joinUrl(input.publicR2Url, uploadKey)
);

// qa fields
const qaPass           = firstDefined(input.qaCombinedPass, input.qaPass, false) === true;
const qaCombinedPass   = qaPass;
const qaScore          = firstDefined(input.qa?.pose?.score, input.qaScore, null);
const styleScore       = firstDefined(input.qa?.style?.score?.style_cohesion, input.styleScore, null);
const qaReasons        = firstDefined(input.qa?.style?.reasons, input.qaReasons, []) || [];

// identity
const characterHash = firstDefined(input.characterHash, input.ctx?.characterHash);
const amazonOrderId = firstDefined(
  input.amazonOrderId,
  input.orderId,
  input.orderContext?.amazonOrderId,
  input.orderContext?.orderId,
  input.orderData?.amazonOrderId,
  input.orderData?.orderId,
  input.__meta?.amazonOrderId,
  input.__meta?.orderId,
  input.__meta?.deriveQaPass?.snapshot?.amazonOrderId,
  input.__meta?.deriveQaPass?.snapshot?.orderId,
  input.__meta?.deriveQaPass?.snapshot?.rootOrderId,
  input.__meta?.deriveQaPass?.snapshot?.orderContext?.amazonOrderId,
  input.__meta?.deriveQaPass?.snapshot?.orderContext?.orderId
);

// build output
return {
  json: {
    success: input.success !== false,
    uploadSuccess: input.success !== false,
    characterHash,
    poseNumber,
    currentPoseNumber: poseNumber,
    amazonOrderId,
    orderId: firstDefined(input.orderId, amazonOrderId),
    retryAttempt: firstDefined(input.retryAttempt, input.retry?.attempt, 0) || 0,
    retryTag: firstDefined(input.retryTag, input.retry?.tag, null),
    qaPass,
    qaCombinedPass,
    qaScore,
    styleScore,
    qaReasons,
    qa: input.qa || null,
    uploadKey,
    storageKey,
    approvedKey: firstDefined(uploadKey, storageKey),
    generatedFileName: input.generatedFileName,
    publicUrl,
    correlationId: input.correlationId,
    replacedAt: input.replacedAt,
    replacementCount: input.replacementCount,
    assetsRoot: input.assetsRoot,
    publicR2Url: input.publicR2Url,
    characterPath: input.characterPath,
    orderContext: input.orderContext || null,
    orderData: input.orderData || null
  },
  binary: {}
};

// Build Gemini flip verdict request from attached pose + generated binaries.
const j = { ...($json || {}) };
const b = $binary || {};
const itemIx = (typeof $itemIndex === 'number') ? $itemIndex : 0;

// Helper: pick first non-empty value.
function first(...vals){ for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; } return null; }
// Helper: infer mime type from a filename.
function mimeFromName(name){
  const s = String(name || '').toLowerCase();
  if (s.endsWith('.jpg') || s.endsWith('.jpeg')) return 'image/jpeg';
  if (s.endsWith('.webp')) return 'image/webp';
  return 'image/png';
}
// Helper: normalize mime labels.
function normMime(v){
